contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, string calldata description) public {
        require(caller != address(this), "test must use a non-team caller");

        address beforeJojoTeam = c.jojoTeam();
        bool reverted;
        try c.newEmergencyOracle(description) {
