contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description) public payable {
        require(bytes(description).length > 0, "description must not be empty");

        uint256 priceBefore;
        uint256 roundBefore;

        bool callSucceeded;
        try c.newEmergencyOracle(description) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        if (callSucceeded) {
            address expectedOracle = address(uint160(uint256(keccak256(abi.encodePacked(
                bytes1(0xff),
                address(c),
                uint256(0),
                keccak256(abi.encodePacked(type(EmergencyOracle).creationCode, abi.encode(address(this), description)))
            )))));
            EmergencyOracle oracle = EmergencyOracle(expectedOracle);
            priceBefore = oracle.price();
            roundBefore = oracle.roundId();
        } else {
            priceBefore = 0;
            roundBefore = 0;
        }

        assert(callSucceeded ? priceBefore == 0 && roundBefore == 0 : true);
    }

    receive() external payable {}
}
